svg.script:
(() => {
  const stages = [
    { title: "Generación de la información", summary: "Los datos se originan durante la atención de cada persona. Cada contacto con la IPS aporta información que puede orientar las decisiones de salud.", label: "La información se origina en", details: ["Consulta externa", "Urgencias", "Hospitalización", "Farmacia", "Laboratorio"] },
    { title: "Registro de los datos", summary: "La información de la atención se deja registrada en sistemas clínicos y administrativos para que pueda consultarse y gestionarse.", label: "Se registra en", details: ["Historia clínica", "Sistemas institucionales", "RIPS", "Registros administrativos"] },
    { title: "Validación de la calidad del dato", summary: "Antes de usar o compartir los datos, se revisa que sean completos, correctos, coherentes y estén disponibles a tiempo.", label: "Criterios de revisión", details: ["Completitud", "Exactitud", "Consistencia", "Oportunidad"] },
    { title: "Consolidación de la información", summary: "Los datos de las distintas áreas se integran para construir una base institucional única que facilite una visión conjunta.", label: "Propósito", details: ["Integrar los datos de todas las áreas", "Construir una base institucional única", "Facilitar el análisis conjunto de la información"] },
    { title: "Reporte y transmisión", summary: "La información consolidada se envía a plataformas y sistemas de reporte del sector salud.", label: "Sistemas de destino", details: ["PISIS", "SISPRO", "SIVIGILA", "RUAF", "REPS"] },
    { title: "Análisis e interpretación", summary: "Los equipos calculan y revisan indicadores para entender el desempeño de la atención y detectar asuntos que requieren seguimiento.", label: "Indicadores revisados", details: ["Calidad", "Seguridad del paciente", "Oportunidad", "Gestión del riesgo", "Satisfacción del usuario"] },
    { title: "Mejora continua", summary: "Los resultados del análisis se convierten en acciones para cerrar brechas y mejorar los procesos de atención.", label: "Acciones de mejora", details: ["Identificar brechas", "Diseñar planes de mejoramiento", "Capacitar al personal", "Hacer seguimiento a las acciones"] }
  ];
  const ns = "http://www.w3.org/2000/svg";
  const panel = document.getElementById("detail-panel");
  const title = document.getElementById("panel-title");
  const summary = document.getElementById("panel-summary");
  const label = document.getElementById("panel-label");
  const detailGroup = document.getElementById("panel-details");
  const previous = document.getElementById("previous-control");
  const next = document.getElementById("next-control");
  let current = 0;
  let lastFocus = null;

  function setLines(node, text, limit, lineHeight, firstY) {
    const words = text.split(/\s+/);
    const lines = [];
    let line = "";
    words.forEach((word) => {
      const candidate = line ? `${line} ${word}` : word;
      if (candidate.length > limit && line) { lines.push(line); line = word; }
      else line = candidate;
    });
    if (line) lines.push(line);
    node.replaceChildren(...lines.map((value, i) => {
      const span = document.createElementNS(ns, "tspan");
      span.setAttribute("x", "193");
      span.setAttribute("y", String(firstY + i * lineHeight));
      span.textContent = value;
      return span;
    }));
    return lines.length;
  }

  function render(index) {
    current = index;
    const stage = stages[index];
    document.getElementById("panel-index").textContent = `ETAPA ${index + 1} DE ${stages.length}`;
    const titleLines = setLines(title, stage.title, 35, 40, 586);
    const summaryY = 602 + titleLines * 39;
    const summaryLines = setLines(summary, stage.summary, 68, 27, summaryY);
    const labelY = summaryY + summaryLines * 27 + 32;
    label.setAttribute("y", String(labelY));
    label.textContent = stage.label.toUpperCase();
    const firstDetailY = labelY + 45;
    detailGroup.replaceChildren(...stage.details.map((value, i) => {
      const group = document.createElementNS(ns, "g");
      const dot = document.createElementNS(ns, "circle");
      dot.setAttribute("class", "bullet"); dot.setAttribute("cx", "199"); dot.setAttribute("cy", String(firstDetailY + i * 36 - 6)); dot.setAttribute("r", "5");
      const text = document.createElementNS(ns, "text");
      text.setAttribute("class", "detail-text"); text.setAttribute("x", "216"); text.setAttribute("y", String(firstDetailY + i * 36)); text.textContent = value;
      group.append(dot, text);
      return group;
    }));
    const navY = Math.min(1081, firstDetailY + stage.details.length * 36 + 24);
    [previous, next].forEach((control) => {
      control.querySelector("rect").setAttribute("y", String(navY - 31));
      control.querySelector("text").setAttribute("y", String(navY));
    });
    previous.classList.toggle("disabled", index === 0);
    previous.setAttribute("aria-disabled", String(index === 0));
    next.classList.toggle("disabled", index === stages.length - 1);
    next.setAttribute("aria-disabled", String(index === stages.length - 1));
  }

  function open(index, source) {
    lastFocus = source;
    render(index);
    panel.setAttribute("visibility", "visible");
    document.querySelector('[data-action="close"]').focus();
  }

  function close() {
    panel.setAttribute("visibility", "hidden");
    if (lastFocus) lastFocus.focus();
  }

  function activate(element) {
    if (element.matches(".hotspot")) open(Number(element.dataset.step), element);
    const action = element.dataset.action;
    if (action === "close") close();
    if (action === "previous" && current > 0) render(current - 1);
    if (action === "next" && current < stages.length - 1) render(current + 1);
  }

  document.querySelectorAll(".hotspot, [data-action]").forEach((element) => {
    element.addEventListener("click", () => activate(element));
    element.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") { event.preventDefault(); activate(element); }
    });
  });
  document.addEventListener("keydown", (event) => {
    if (panel.getAttribute("visibility") !== "visible") return;
    if (event.key === "Escape") close();
    if (event.key === "ArrowLeft" && current > 0) render(current - 1);
    if (event.key === "ArrowRight" && current < stages.length - 1) render(current + 1);
  });
})();
